// lib/pdf/generator.ts
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";

// School configuration from environment variables
const SCHOOL_CONFIG = {
  name: process.env.SCHOOL_NAME || "KIDDIEWISE SCHOOL COMPLEX",
  address:
    process.env.SCHOOL_ADDRESS ||
    "Oyarifa Road (Off Container Junction), Accra, Ghana",
  phone: process.env.SCHOOL_PHONE || "+233(0) 54 179 0780",
  email: process.env.SCHOOL_EMAIL || "kiddiewise2012@gmail.com",
  logoBase64:
    "",
};

// Helper to add logo to PDF
async function addLogoToPDF(doc: jsPDF): Promise<void> {
  return new Promise((resolve) => {
    try {
      if (SCHOOL_CONFIG.logoBase64) {
        // Add logo at position (x: 20, y: 15, width: 30, height: 30)
        doc.addImage(SCHOOL_CONFIG.logoBase64, "JPEG", 20, 15, 30, 30);
      }
      resolve();
    } catch (error) {
      console.log("Logo not available:", error);
      resolve();
    }
  });
}

// Helper to add school header
function addSchoolHeader(doc: jsPDF): void {
  doc.setFontSize(18);
  doc.setTextColor(30, 58, 95);
  doc.text(SCHOOL_CONFIG.name, 105, 30, { align: "center" });

  doc.setFontSize(10);
  doc.setTextColor(100, 100, 100);
  doc.text(SCHOOL_CONFIG.address, 105, 38, { align: "center" });
  doc.text(
    `Tel: ${SCHOOL_CONFIG.phone} | Email: ${SCHOOL_CONFIG.email}`,
    105,
    44,
    { align: "center" },
  );
}

interface FeeReceiptData {
  logo?: string;
  receiptNo?: string;
  date?: string;
  studentName?: string;
  studentId?: string;
  term?: string;
  academicYear?: string;
  receivedFrom?: string;
  paymentType?: string;
  paymentFor?: string;
  amountPaid?: number;
  fees?: Array<{ description: string; amount: number }>;
  total?: number;
  balance?: number;
  totalFees?: number | null;
  paymentMethod?: string;
  paymentDate?: string;
  handwrittenNote?: string;
  className?: string;
  recordedBy?: string;
}

export async function generateFeeReceiptPDF(
  data: FeeReceiptData,
): Promise<string> {
  const doc = new jsPDF();

  // Add logo
  await addLogoToPDF(doc);

  // School Header
  addSchoolHeader(doc);

  // Title
  doc.setFontSize(14);
  doc.setTextColor(0, 0, 0);
  doc.text("SCHOOL FEES RECEIPT", 105, 58, { align: "center" });

  // Receipt Info Line
  doc.setFontSize(9);
  doc.text(`Receipt No: ${data.receiptNo || "_____________"}`, 150, 70);
  doc.text(`Date: ${data.date || new Date().toLocaleDateString()}`, 150, 76);

  // Student Information Table
  autoTable(doc, {
    startY: 85,
    body: [
      [
        "Student Name:",
        data.studentName || "_________________________",
        "Student ID:",
        data.studentId || "_____________",
      ],
      [
        "Class:",
        data.className || "_____________",
        "Term:",
        data.term || "_____________",
      ],
      [
        "Academic Year:",
        data.academicYear || "_____________",
        "Payment Method:",
        data.paymentMethod || "_____________",
      ],
    ],
    theme: "plain",
    styles: { fontSize: 10, cellPadding: 4 },
    columnStyles: {
      0: { cellWidth: 35, fontStyle: "bold" },
      1: { cellWidth: 65 },
      2: { cellWidth: 35, fontStyle: "bold" },
      3: { cellWidth: 45 },
    },
  });

  // Received From Section
  let y = (doc as any).lastAutoTable.finalY + 10;
  doc.setFontSize(10);
  doc.setFont("helvetica", "bold");
  doc.text("Received From:", 20, y);
  doc.setFont("helvetica", "normal");
  doc.text(data.receivedFrom || "_________________________", 70, y);

  y += 8;
  doc.setFont("helvetica", "bold");
  doc.text("Payment Type:", 20, y);
  doc.setFont("helvetica", "normal");
  doc.text(data.paymentType || "School Fees", 70, y);

  y += 8;
  doc.setFont("helvetica", "bold");
  doc.text("Payment For:", 20, y);
  doc.setFont("helvetica", "normal");
  doc.text(data.paymentFor || data.term || "Term Fees", 70, y);

  // Fees Table
  const feeRows = (data.fees || []).map((fee) => [
    fee.description,
    `GHS ${(fee.amount || 0).toFixed(2)}`,
  ]);

  if (feeRows.length === 0 && data.amountPaid) {
    feeRows.push([
      "Payment Received",
      `GHS ${(data.amountPaid || 0).toFixed(2)}`,
    ]);
  }

  autoTable(doc, {
    startY: y + 8,
    head: [["Description", "Amount (GHS)"]],
    body: feeRows,
    foot: [
      ["Total Paid", `GHS ${(data.total || data.amountPaid || 0).toFixed(2)}`],
    ],
    theme: "striped",
    headStyles: { fillColor: [30, 58, 95], textColor: 255, fontSize: 10 },
    footStyles: { fillColor: [240, 240, 240], textColor: 0, fontStyle: "bold" },
    styles: { fontSize: 9, cellPadding: 5 },
  });

  // Balance and Payment Summary
  const finalY = (doc as any).lastAutoTable.finalY + 10;
  autoTable(doc, {
    startY: finalY,
    body: [
      [
        "Balance:",
        `______________________`,
        "Total Fees:",
        `GHS ${(data.totalFees || 0).toFixed(2)}`,
      ],
      [
        "Payment Date:",
        data.paymentDate || new Date().toLocaleDateString(),
        "Recorded By:",
         "Admin",
      ],
    ],
    theme: "plain",
    styles: { fontSize: 10, cellPadding: 4 },
    columnStyles: {
      0: { cellWidth: 30, fontStyle: "bold" },
      1: { cellWidth: 60 },
      2: { cellWidth: 30, fontStyle: "bold" },
      3: { cellWidth: 60 },
    },
  });

  // Handwritten Note Section
  if (data.handwrittenNote) {
    const noteY = (doc as any).lastAutoTable.finalY + 15;
    doc.setFontSize(9);
    doc.setTextColor(100, 100, 100);
    doc.text("Notes:", 20, noteY);
    doc.text(data.handwrittenNote, 20, noteY + 5);
  }

  // Footer
  const pageHeight = doc.internal.pageSize.height;
  doc.setFontSize(8);
  doc.setTextColor(150, 150, 150);
  doc.text("Thank you for your payment!", 105, pageHeight - 15, {
    align: "center",
  });
  doc.text("This is a computer-generated receipt.", 105, pageHeight - 10, {
    align: "center",
  });

  return doc.output("datauristring");
}

// Terminal Report Data Interface
interface TerminalReportData {
  logo?: string;
  studentName?: string;
  studentId?: string;
  className?: string;
  term?: string;
  position?: string;
  academicYear?: string;
  reopeningDate?: string;
  subjects?: Array<{
    subject: string;
    classScore: string;
    examScore: string;
    totalScore: string;
    letterGrade?: string;
    grade?: string;
    remarks: string;
  }>;
  subjectAssessments?: Array<{
    subject: string;
    performance?: {
      score?: number;
      description?: string;
      recommendation?: string;
    };
    attitude?: {
      score?: number;
      description?: string;
      recommendation?: string;
    };
    behavior?: {
      score?: number;
      description?: string;
      recommendation?: string;
    };
    participation?: {
      score?: number;
      description?: string;
      recommendation?: string;
    };
  }>;
  classTeacherRemarks?: string;
  interest?: string;
  promotedTo?: string;
  attitude?: string;
  handwrittenNote?: string;
  overallAverage?: string;
  overallLetterGrade?: string;
  overallRemarks?: string;
  defaultAssessmentWeight?: number;
  defaultExamWeight?: number;
  subjectCount?: number;
  subjectsWithGrades?: number;
  subjectsWithoutGrades?: number;
}

export async function generateTerminalReportPDF(
  data: TerminalReportData,
): Promise<string> {
  const doc = new jsPDF();

  // Add logo
  await addLogoToPDF(doc);

  // School Header
  addSchoolHeader(doc);

  // Title
  doc.setFontSize(14);
  doc.setTextColor(0, 0, 0);
  doc.text("TERMINAL REPORT", 105, 58, { align: "center" });

  // Student Information Grid
  autoTable(doc, {
    startY: 70,
    body: [
      [
        "Student Name:",
        data.studentName || "_________________________",
        "Student ID:",
        data.studentId || "_____________",
      ],
      [
        "Class:",
        data.className || "_____________",
        "Term:",
        data.term || "_____________",
      ],
      [
        "Overall Average:",
        data.overallAverage ? `${data.overallAverage}%` : "_____________",
        "Overall Grade:",
        data.overallLetterGrade || "_____________",
      ],
      [
        "Academic Year:",
        data.academicYear || "_____________",
        "Reopening Date:",
        data.reopeningDate || "_____________",
      ],
    ],
    theme: "plain",
    styles: { fontSize: 10, cellPadding: 5 },
    columnStyles: {
      0: { cellWidth: 35, fontStyle: "bold" },
      1: { cellWidth: 60 },
      2: { cellWidth: 35, fontStyle: "bold" },
      3: { cellWidth: 50 },
    },
  });

  // Note about grade weights
  let y = (doc as any).lastAutoTable.finalY + 5;
  doc.setFontSize(8);
  doc.setTextColor(100, 100, 100);
  doc.text(
    `* Assessment Weight: ${data.defaultAssessmentWeight || 70}% | Exam Weight: ${data.defaultExamWeight || 30}%`,
    20,
    y,
  );
  y += 8;

  // Subjects Table
  const subjectRows = (data.subjects || []).map((subject) => [
    subject.subject,
    `${subject.classScore}%`,
    `${subject.examScore}%`,
    `${subject.totalScore}%`,
    subject.letterGrade || subject.grade || "-",
    subject.remarks || "-",
  ]);

  if (subjectRows.length > 0) {
    autoTable(doc, {
      startY: y + 5,
      head: [
        [
          "Subject",
          "Class Score",
          "Exam Score",
          "Total Score",
          "Grade",
          "Remarks",
        ],
      ],
      body: subjectRows,
      theme: "striped",
      headStyles: { fillColor: [30, 58, 95], textColor: 255, fontSize: 9 },
      styles: { fontSize: 8, cellPadding: 4 },
      columnStyles: {
        0: { cellWidth: 45 },
        1: { cellWidth: 25, halign: "center" },
        2: { cellWidth: 25, halign: "center" },
        3: { cellWidth: 25, halign: "center" },
        4: { cellWidth: 20, halign: "center" },
        5: { cellWidth: 35 },
      },
    });
    y = (doc as any).lastAutoTable.finalY + 10;
  } else {
    y += 10;
    doc.setFontSize(10);
    doc.setTextColor(150, 0, 0);
    doc.text("No subject grades available for this term.", 20, y);
    y += 15;
  }

  // Subject Summary
  if (data.subjectCount) {
    doc.setFontSize(9);
    doc.setTextColor(80, 80, 80);
    doc.text(
      `Subjects Offered: ${data.subjectCount} | With Grades: ${data.subjectsWithGrades || 0} | Without Grades: ${data.subjectsWithoutGrades || 0}`,
      20,
      y,
    );
    y += 10;
  }

  // Teacher Assessments Section (if available)
  if (data.subjectAssessments && data.subjectAssessments.length > 0) {
    doc.setFontSize(11);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(0, 0, 0);
    doc.text("Teacher's Comments", 20, y);

    y += 8;
    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(100, 100, 100);

    for (const assessment of data.subjectAssessments) {
      if (
        assessment.performance?.description ||
        assessment.attitude?.description ||
        assessment.behavior?.description ||
        assessment.participation?.description
      ) {
        if (y > 250) {
          doc.addPage();
          y = 20;
        }

        doc.setFont("helvetica", "bold");
        doc.text(`${assessment.subject}:`, 25, y);
        y += 5;
        doc.setFont("helvetica", "normal");

        if (assessment.performance?.description) {
          doc.text(
            `  Performance: ${assessment.performance.description}`,
            30,
            y,
          );
          y += 5;
        }
        if (assessment.attitude?.description) {
          doc.text(`  Attitude: ${assessment.attitude.description}`, 30, y);
          y += 5;
        }
        if (assessment.behavior?.description) {
          doc.text(`  Behavior: ${assessment.behavior.description}`, 30, y);
          y += 5;
        }
        if (assessment.participation?.description) {
          doc.text(
            `  Participation: ${assessment.participation.description}`,
            30,
            y,
          );
          y += 5;
        }
        y += 3;
      }
    }
  }

  // Overall Performance Section
  if (y > 250) {
    doc.addPage();
    y = 20;
  }

  doc.setFontSize(10);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(0, 0, 0);
  doc.text("Overall Performance", 20, y);
  y += 8;

  doc.setFont("helvetica", "normal");
  doc.text(
    `Overall Remarks: ${data.overallRemarks || "_________________________"}`,
    20,
    y,
  );
  y += 10;

  // Additional Info Section
  if (y > 260) {
    doc.addPage();
    y = 20;
  }

  doc.setFont("helvetica", "bold");
  doc.text("Additional Information", 20, y);
  y += 8;

  doc.setFont("helvetica", "bold");
  doc.text("Class Teacher's Remarks:", 20, y);
  doc.setFont("helvetica", "normal");
  doc.text(data.classTeacherRemarks || "_________________________", 70, y);

  y += 12;
  if (y > 270) {
    doc.addPage();
    y = 20;
  }

  doc.setFont("helvetica", "bold");
  doc.text("Interest:", 20, y);
  doc.setFont("helvetica", "normal");
  doc.text(data.interest || "_________________________", 70, y);

  y += 8;
  doc.setFont("helvetica", "bold");
  doc.text("Attitude:", 20, y);
  doc.setFont("helvetica", "normal");
  doc.text(data.attitude || "_________________________", 70, y);

  y += 8;
  doc.setFont("helvetica", "bold");
  doc.text("Promoted to:", 20, y);
  doc.setFont("helvetica", "normal");
  doc.text(data.promotedTo || "_________________________", 70, y);

  // Handwritten Note
  if (data.handwrittenNote) {
    y += 20;
    if (y > 270) {
      doc.addPage();
      y = 20;
    }
    doc.setFontSize(9);
    doc.setTextColor(100, 100, 100);
    doc.text("Additional Notes:", 20, y);
    doc.text(data.handwrittenNote, 20, y + 5);
  }

  // Signatures
  const pageHeight = doc.internal.pageSize.height;
  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(0, 0, 0);
  doc.text(
    "Parent's Signature: _________________________",
    30,
    pageHeight - 25,
  );
  doc.text(
    "Teacher's Signature: _________________________",
    30,
    pageHeight - 15,
  );

  return doc.output("datauristring");
}


export async function generateExtraFeeReceiptPDF(
  data: FeeReceiptData & { feeType?: string; frequency?: string }
): Promise<string> {
  const doc = new jsPDF();

  await addLogoToPDF(doc);
  addSchoolHeader(doc);

  doc.setFontSize(14);
  doc.setTextColor(0, 0, 0);
  doc.text("EXTRA FEE RECEIPT", 105, 58, { align: "center" });

  // Receipt Info Line
  doc.setFontSize(9);
  doc.text(`Receipt No: ${data.receiptNo || "_____________"}`, 150, 70);
  doc.text(`Date: ${data.date || new Date().toLocaleDateString()}`, 150, 76);

  // Student Information Table - Now displays actual data
  autoTable(doc, {
    startY: 85,
    body: [
      [
        "Student Name:",
        data.studentName || "_________________________",
        "Student ID:",
        data.studentId || "_____________"
      ],
      [
        "Class:",
        data.className || "_________________________",
        "Fee Type:",
        data.feeType || "_________________________"
      ],
      [
        "Frequency:",
        data.frequency || "_________________________",
        "Payment Method:",
        data.paymentMethod || "_________________________"
      ],
    ],
    theme: "plain",
    styles: { fontSize: 10, cellPadding: 4 },
    columnStyles: {
      0: { cellWidth: 35, fontStyle: "bold" },
      1: { cellWidth: 65 },
      2: { cellWidth: 35, fontStyle: "bold" },
      3: { cellWidth: 45 },
    },
  });

  // Received From Section
  let y = (doc as any).lastAutoTable.finalY + 10;
  doc.setFontSize(10);
  doc.setFont("helvetica", "bold");
  doc.text("Received From:", 20, y);
  doc.setFont("helvetica", "normal");
  doc.text(data.receivedFrom || data.studentName || "_________________________", 70, y);

  y += 8;
  doc.setFont("helvetica", "bold");
  doc.text("Payment For:", 20, y);
  doc.setFont("helvetica", "normal");
  doc.text(data.paymentFor || data.feeType || "Extra Fee", 70, y);

  // Fees Table with Total and Balance
  const feeRows = [];
  
  // Add the fee description
  feeRows.push([data.feeType || "Extra Fee", `GHS ${(data.amountPaid || 0).toFixed(2)}`]);
  
  // Add total fees row if available
  if (data.totalFees && data.totalFees > 0) {
    feeRows.push(["Total Fees", `GHS ${(data.totalFees || 0).toFixed(2)}`]);
  }

  autoTable(doc, {
    startY: y + 8,
    head: [["Description", "Amount (GHS)"]],
    body: feeRows,
    foot: [
      ["Total Paid", `GHS ${(data.total || data.amountPaid || 0).toFixed(2)}`],
      ...(data.balance !== undefined && data.balance !== null ? [
        ["Balance", `GHS ${(data.balance || 0).toFixed(2)}`]
      ] : []),
    ],
    theme: "striped",
    headStyles: { fillColor: [30, 58, 95], textColor: 255, fontSize: 10 },
    footStyles: { fillColor: [240, 240, 240], textColor: 0, fontStyle: "bold" },
    styles: { fontSize: 9, cellPadding: 5 },
  });

  // Payment Summary
  const finalY = (doc as any).lastAutoTable.finalY + 10;
  autoTable(doc, {
    startY: finalY,
    body: [
      [
        "Total Fees:",
        `GHS ${(data.totalFees || 0).toFixed(2)}`,
        "Balance:",
        `GHS ${(data.balance !== undefined && data.balance !== null ? data.balance : 0).toFixed(2)}`
      ],
      [
        "Payment Date:",
        data.paymentDate || new Date().toLocaleDateString(),
        "Recorded By:",
        data.recordedBy || "System"
      ],
    ],
    theme: "plain",
    styles: { fontSize: 10, cellPadding: 4 },
    columnStyles: {
      0: { cellWidth: 30, fontStyle: "bold" },
      1: { cellWidth: 60 },
      2: { cellWidth: 30, fontStyle: "bold" },
      3: { cellWidth: 60 },
    },
  });

  // Handwritten Note Section
  if (data.handwrittenNote) {
    const noteY = (doc as any).lastAutoTable.finalY + 15;
    doc.setFontSize(9);
    doc.setTextColor(100, 100, 100);
    doc.text("Notes:", 20, noteY);
    doc.text(data.handwrittenNote, 20, noteY + 5);
  }

  // Footer
  const pageHeight = doc.internal.pageSize.height;
  doc.setFontSize(8);
  doc.setTextColor(150, 150, 150);
  doc.text("Thank you for your payment!", 105, pageHeight - 15, { align: "center" });
  doc.text("This is a computer-generated receipt.", 105, pageHeight - 10, { align: "center" });

  return doc.output("datauristring");
}


export async function generatePaymentReceipt(
  receiptData: FeeReceiptData,
): Promise<string> {
  return generateFeeReceiptPDF(receiptData);
}


